    t = rng.randint(2, 8)
    n = (d + 1) * t
    # Choose a positive rational energy p/q with q >= 2 to avoid trivial integer-only cases
    p = rng.randint(2, 60)
    q = rng.randint(2, 60)
    # Reduce p/q
    g = math.gcd(p, q)
    p //= g
    q //= g
    # Assemble assignment
    assign = {
        'n_points': n,
        'dimension': d,
        'energy_num': p,
        'energy_den': q
    }
    return assign

